    example: program('Settings settings = new Settings(3);\nvar field = Settings.class.getDeclaredField("limit");\nfield.setAccessible(true);\ntry {\n  field.setInt(settings, 7);\n  throw new AssertionError("mutation unexpectedly allowed");\n} catch (IllegalAccessException expected) { System.out.println("blocked"); }', 'static final class Settings {\n  private final int limit;\n  Settings(int limit) { this.limit = limit; }\n}'), output: 'blocked',
