    example: program('System.out.println(CALLS.get());\nSystem.out.println(VALUE.get());\nSystem.out.println(VALUE.get());\nSystem.out.println(CALLS.get());', 'static final java.util.concurrent.atomic.AtomicInteger CALLS = new java.util.concurrent.atomic.AtomicInteger();\nstatic final LazyConstant<Integer> VALUE = LazyConstant.of(() -> { CALLS.incrementAndGet(); return 42; });'), output: '0\n42\n42\n1',
