export const JAVA_RELEASE_CHAPTERS = Object.fromEntries(lessons.map(lesson => {
  const preview = lesson.status === 'preview';
  const compileArgs = ['--release', String(lesson.release), ...(preview ? ['--enable-preview'] : []), ...(lesson.compileExtra || [])];
  const runArgs = [...(preview ? ['--enable-preview'] : []), ...(lesson.runExtra || [])];
  const source = lesson.example;
  return [lesson.title, {
    ...lesson, category: 'Java by release', level: 'Intermediate', javaVersions: `${lesson.release}${preview ? ' only · preview' : lesson.status === 'incubator' ? ' only · incubator' : '+'}`,
    status: lesson.status || 'permanent', since: lesson.since || String(lesson.release),
    summary: lesson.beginner, why: lesson.walkthrough, failure: lesson.mistakes, complexity: lesson.benchmark, edgeCases: lesson.solution,
    diagram: lesson.trace.join(' → '), diagramSteps: lesson.trace.map((detail, index) => [`Step ${index + 1}`, detail]),
    interviewAnswer: `${lesson.beginner} ${lesson.walkthrough} In the example, ${lesson.trace.join('; ')}. ${lesson.benchmark}`,
    references: [{ title: `Primary reference: ${lesson.title}`, url: lesson.reference }, ...(lesson.extraReferences || [])],
    runnableExample: { source, filename: 'ReleaseExample.java', className: 'ReleaseExample', output: lesson.output, release: lesson.release, compileArgs, runArgs, commands: [{ label: 'Compile the complete example', code: `javac ${compileArgs.join(' ')} -d out ReleaseExample.java` }, { label: 'Run the complete example', code: `java ${runArgs.length ? runArgs.join(' ') + ' ' : ''}-cp out ReleaseExample` }] },
    teaching: { beginner: lesson.beginner, traceSteps: lesson.trace, followUp: lesson.followUp, solution: lesson.solution },
  }];
}));
// Teach var before the factory/stream examples that use it. The separate release
// map preserves historical chronology without weakening learning prerequisites.
const learningTitles = [lessons[0].title, 'Local variable type inference', ...lessons.slice(1).map(lesson => lesson.title).filter(title => title !== 'Local variable type inference')];
export const JAVA_RELEASE_SEEDS = learningTitles.map(title => {
  const lesson = JAVA_RELEASE_CHAPTERS[title];
  return [title, lesson.category, lesson.level];
});
